def shortest_path(graph, source, target):
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    path = {node: None for node in graph}
    priority_queue = [(0, source)]
    while priority_queue:
        current_distance, current_node = priority_queue[0]
        priority_queue = [(d, n) for d, n in priority_queue if d <= current_distance]
        if not priority_queue:
            break
        for neighbor, weight in graph[current_node]:
            distance_to_neighbor = current_distance + weight
            if distance_to_neighbor < distance[neighbor]:
                distance[neighbor] = distance_to_neighbor
                path[neighbor] = current_node
                priority_queue.append((distance_to_neighbor, neighbor))
        priority_queue.remove((current_distance, current_node))
    if distance[target] == float('inf'):
        return (float('inf'), None)
    else:
        path_list = []
        node = target
        while node is not None:
            path_list.append(node)
            node = path[node]
        return (distance[target], path_list[::-1])

from collections import defaultdict, deque
import sys

def shortest_path(graph, source, target):
    shortest_dist = {node: sys.maxsize for node in graph}
    shortest_dist[source] = 0
    queue = deque([(source, 0)])
    while queue:
        current_node, current_dist = queue.popleft()
        if current_node == target:
            return (current_dist, [target] + shortest_dist[target_reverse_path(target, graph)])
        for neighbor, weight in graph[current_node]:
            new_dist = current_dist + weight
            if new_dist < shortest_dist[neighbor]:
                shortest_dist[neighbor] = new_dist
                queue.append((neighbor, new_dist))
    return (float('inf'), None)

def target_reverse_path(target, graph):
    path = []
    current_node = target
    while current_node is not None:
        path.append(current_node)
        current_node = graph[current_node][0]
    return path[::-1]
